#include <stdio.h>

int main() {
    char name[100];
    int i = 0, lastSpace = -1;

    printf("Input:\nEnter a name: ");
    scanf("%[^\n]", name);

    while(name[i] != '\0') {
        if(name[i] == ' ') {
            lastSpace = i;
        }
        i++;
    }

    printf("Output:\nAbbreviated name is: ");
    if(lastSpace != -1) {
        printf("%c.", name[0]);
        for(i=1; i<lastSpace; i++) {
            if(name[i] == ' ' && name[i+1] != ' ') {
                printf("%c.", name[i+1]);
            }
        }
        for(i=lastSpace+1; name[i] != '\0'; i++) {
            printf("%c", name[i]);
        }
        printf("\n");
    } else {
        printf("%s\n", name);
    }

    return 0;
}

