#include <stdio.h>

void checkPrime(int num) {
    int isPrime = 1;
    if (num <= 1) {
        isPrime = 0;
    } else {
        for (int i = 2; i <= num / 2; i++) {
            if (num % i == 0) {
                isPrime = 0;
                break;
            }
        }
    }

    if (isPrime) {
        printf("%d is a Prime number.\n", num);
    } else {
        printf("%d is not a Prime number.\n", num);
    }
}

int main() {
    int n;
    printf("Enter a number: ");
    scanf("%d", &n);
    checkPrime(n);
    return 0;
}

#include <stdio.h>

long long calculateFactorial(int num) {
    long long fact = 1;
    for (int i = 1; i <= num; i++) {
        fact *= i;
    }
    return fact;
}

int main() {
    int num;
    printf("Enter a number: ");
    scanf("%d", &num);
    printf("Factorial of %d is: %lld\n", num, calculateFactorial(num));
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x, y;
    printf("Enter two integers (x and y): ");
    scanf("%d %d", &x, &y);

    printf("Before Swapping: x = %d, y = %d\n", x, y);
    swap(&x, &y);
    printf("After Swapping: x = %d, y = %d\n", x, y);

    return 0;
}
